The parseRetryDelay method doesn't handle null or undefined input. If retryAfter is null/undefined, calling retryAfter.at(-1) will throw a runtime error.
```suggestion
	private parseRetryDelay(retryAfter: string | null | undefined): number {
		if (!retryAfter) {
			console.warn("Invalid retryAfter value: null or undefined. Defaulting to 0 seconds.");
			return 0; // Default to 0 seconds if input is invalid
		}

		const unit = retryAfter.at(-1);
		const value = parseInt(retryAfter, 10);

		if (unit === "s") {
			return value; // Return seconds
		} else if (unit === "m") {
			return value * 60; // Convert minutes to seconds
		} else if (unit === "h") {
			return value * 60 * 60; // Convert hours to seconds
		}

		return value;
```

