import { getAsVar, VSC_INACTIVE_SELECTION_BACKGROUND } from "@/utils/vscStyles"

export const CURRENT_CLI_BANNER_VERSION = 1

// Centralized polling hook for CLI installation status
function useCliInstallationStatus(): boolean {
	const [, forceUpdate] = useState(0)
	const statusRef = useRef<boolean>(false)

	// Singleton state for polling
	const listenersRef = useRef<Set<() => void>>()
	if (!listenersRef.current) {
		listenersRef.current = new Set()
	}

	// Singleton polling interval
	const intervalRef = useRef<NodeJS.Timeout | null>(null)

	useEffect(() => {
		let isMounted = true
		const updateStatus = (value: boolean) => {
			if (statusRef.current !== value) {
				statusRef.current = value
				listenersRef.current!.forEach(listener => listener())
			}
		}

		const checkInstallation = async () => {
			try {
				const result = await StateServiceClient.checkCliInstallation(EmptyRequest.create())
				updateStatus(result.value)
			} catch (error) {
				console.error("Failed to check CLI installation:", error)
			}
		}

		// Add this component's forceUpdate as a listener
		const listener = () => { if (isMounted) forceUpdate(n => n + 1) }
		listenersRef.current!.add(listener)

		// Start polling if not already started
		if (!intervalRef.current) {
