			isMounted = false
			listenersRef.current!.delete(listener)
			// If no listeners left, clear interval
			if (listenersRef.current!.size === 0 && intervalRef.current) {
				clearInterval(intervalRef.current)
				intervalRef.current = null
			}
		}
	}, [])

