There's a race condition between the timeout handler (line 462-472) and the completion/error handlers (lines 477-501). If the process completes or errors exactly at the 10-minute mark, both handlers could execute concurrently, leading to:
1. Multiple calls to logStream.end()
2. Status being set to both "timed_out" and "completed"/"error"

Consider adding a check in the timeout handler to verify the timeout is still in the map before proceeding, or use once() for the event listeners.
```suggestion
		let finalized = false;
		const finalizeBackgroundCommand = (status: "completed" | "error" | "timed_out", error?: Error) => {
			if (finalized) return;
			finalized = true;
			const timeout = this.backgroundTimeouts.get(id);
			if (timeout) {
				clearTimeout(timeout);
				this.backgroundTimeouts.delete(id);
			}
			backgroundCommand.status = status;
			if (status === "timed_out") {
				logStream.write("\n[TIMEOUT] Process killed after 10 minutes\n");
			}
			if (status === "error" && error) {
				// Try to extract exit code from error message if available
				const exitCodeMatch = error.message.match(/exit code (\d+)/);
				if (exitCodeMatch) {
					backgroundCommand.exitCode = parseInt(exitCodeMatch[1], 10);
				}
			}
			logStream.end();
		};

		const timeoutId = setTimeout(() => {
			// Only proceed if not already finalized
			if (!finalized && backgroundCommand.status === "running" && this.backgroundTimeouts.has(id)) {
				finalizeBackgroundCommand("timed_out");
				// Terminate the process if it has a terminate method
				if (process && typeof (process as any).terminate === "function") {
					;(process as any).terminate();
				}
			}
		}, BACKGROUND_COMMAND_TIMEOUT_MS);
		this.backgroundTimeouts.set(id, timeoutId);

		// Listen for completion - clear timeout
		process.once("completed", () => {
			finalizeBackgroundCommand("completed");
		});

		// Listen for errors - clear timeout
		process.once("error", (error: Error) => {
			finalizeBackgroundCommand("error", error);
		});
